		{"ok = 1\nsp ace = 2\n", 2, "invalid key"},
	}
	for _, c := range cases {
		_, err := Parse(c.text)
		var pe *ParseError
		if !errors.As(err, &pe) {
			t.Errorf("Parse(%q): want *ParseError, got %v", c.text, err)
			continue
		}
		if pe.Line != c.line || !strings.Contains(pe.Msg, c.sub) {
