        self.name = name
        self.stats = dict(stats or {})
        self.inventory = [dict(item) for item in (inventory or [])]
        self.tags = list(tags or [])

    def find(self, name):
        for item in self.inventory:
            if item["name"] == name:
                return item
        return None

