class History:
    def __init__(self):
        self._stack = []

    def commit(self, sheet):
        self._stack.append(sheet.snapshot())

    def undo(self, sheet):
        if not self._stack:
            return False
        sheet.restore(self._stack.pop())
        return True

    def depth(self):
        return len(self._stack)

