        self.assertEqual(next_daily(K, D(2025, 9, 30, 3, 0), 9, 0), D(2025, 10, 1, 4, 0))
        self.assertEqual(next_daily(K, D(2025, 9, 29, 3, 0), 9, 0), D(2025, 9, 30, 3, 0))

