public final class Statement {
    private Statement() {}

    public static long[] shares(long[] lineAmounts, int vatBp, int owners) {
        long total = 0;
        for (long line : lineAmounts) {
            total += line + Fees.percentOf(line, vatBp);
        }
        return Fees.split(total, owners);
    }
}

